/**
 * Risk level classification for an AI-generated shell command.
 */

enum class AiRiskLevel {
    /**
     * Read-only or benign operations (ls, grep, cat, docker ps, git status).
     */
    SAFE,

    /**
     * Requires elevated root/admin privileges (sudo, doas, chown, chmod).
     */
    ELEVATED,

    /**
     * Modifies files, services, or repository state (git checkout, kill, systemctl stop).
     */
    CAUTION,

    /**
     * High-risk or irreversible destructive operations (rm -rf, dd, mkfs, git reset --hard, dropdb).
     */
    DESTRUCTIVE,

    ;

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAiRiskLevel : FfiConverterRustBuffer<AiRiskLevel> {
    override fun read(buf: ByteBuffer) =
        try {
            AiRiskLevel.values()[buf.getInt() - 1]
        } catch (e: IndexOutOfBoundsException) {
            throw RuntimeException("invalid enum value, something is very wrong!!", e)
        }

    override fun allocationSize(value: AiRiskLevel) = 4UL

    override fun write(
        value: AiRiskLevel,
        buf: ByteBuffer,
    ) {
        buf.putInt(value.ordinal + 1)
    }
}

sealed class SessionState {
    object Disconnected : SessionState()

    object Connecting : SessionState()

    object Connected : SessionState()

    object Reconnecting : SessionState()

    data class Failed(
        val `reason`: kotlin.String,
    ) : SessionState() {
        companion object
    }

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeSessionState : FfiConverterRustBuffer<SessionState> {
    override fun read(buf: ByteBuffer): SessionState =
        when (buf.getInt()) {
            1 -> {
                SessionState.Disconnected
            }

            2 -> {
                SessionState.Connecting
            }

            3 -> {
                SessionState.Connected
            }

            4 -> {
                SessionState.Reconnecting
            }

            5 -> {
                SessionState.Failed(
                    FfiConverterString.read(buf),
                )
            }

            else -> {
                throw RuntimeException("invalid enum value, something is very wrong!!")
            }
        }

    override fun allocationSize(value: SessionState): ULong =
        when (value) {
            is SessionState.Disconnected -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }

            is SessionState.Connecting -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }

            is SessionState.Connected -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }

            is SessionState.Reconnecting -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL
                )
            }

            is SessionState.Failed -> {
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                (
                    4UL +
                        FfiConverterString.allocationSize(value.`reason`)
                )
            }
        }

    override fun write(
        value: SessionState,
        buf: ByteBuffer,
    ) {
        when (value) {
            is SessionState.Disconnected -> {
                buf.putInt(1)
                Unit
            }

            is SessionState.Connecting -> {
                buf.putInt(2)
                Unit
            }

            is SessionState.Connected -> {
                buf.putInt(3)
                Unit
            }

            is SessionState.Reconnecting -> {
                buf.putInt(4)
                Unit
            }

            is SessionState.Failed -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

sealed class SshCoreException : kotlin.Exception() {
    class KeyGenerationException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class KeyParseException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class InvalidSessionName(
        val `name`: kotlin.String,
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "name=${ `name` }, reason=${ `reason` }"
    }

    class ConnectionException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class AuthenticationException(
        val `username`: kotlin.String,
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "username=${ `username` }, reason=${ `reason` }"
    }

    class ChannelException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class IoException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class AlreadyConnected : SshCoreException() {
        override val message
            get() = ""
    }

    class NotConnected : SshCoreException() {
        override val message
            get() = ""
    }

    class Timeout : SshCoreException() {
        override val message
            get() = ""
    }

    class ApprovalVerificationException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class InvalidApprovalPayload(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class PortForwardFailed(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class LocalPortInUse(
        val `port`: kotlin.UShort,
    ) : SshCoreException() {
        override val message
            get() = "port=${ `port` }"
    }

    class RemotePortRefused(
        val `port`: kotlin.UShort,
    ) : SshCoreException() {
        override val message
            get() = "port=${ `port` }"
    }

    class AiAssistantException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class AiResponseParseException(
        val `reason`: kotlin.String,
    ) : SshCoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SshCoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): SshCoreException = FfiConverterTypeSshCoreError.lift(error_buf)
    }
}

