                FfiConverterString.write(value.`reason`, buf)
                Unit
            }

            is SshCoreException.InvalidApprovalPayload -> {
                buf.putInt(12)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }

            is SshCoreException.PortForwardFailed -> {
                buf.putInt(13)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }

            is SshCoreException.LocalPortInUse -> {
                buf.putInt(14)
                FfiConverterUShort.write(value.`port`, buf)
                Unit
            }

            is SshCoreException.RemotePortRefused -> {
                buf.putInt(15)
                FfiConverterUShort.write(value.`port`, buf)
                Unit
            }

            is SshCoreException.AiAssistantException -> {
                buf.putInt(16)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }

            is SshCoreException.AiResponseParseException -> {
                buf.putInt(17)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}

